import {createVertice,legalVerticeMoves,applyVerticeMove,previewVerticeMove,undoVertice,redoVertice,resetVertice,rematchVertice,restoreVertice,serializeVertice,VERTICE_WIN_EXAMPLE,deriveControl,VERTICE_EDGES} from './engine.mjs';
import {DEFAULT_MASCOTS,normalizeMascots,mascotIcon,mascotOptions,mascotName} from '../versus-mascots.mjs';
import {createVerticeSearch} from './service.mjs';
import {createRestartConfirmation} from '../restart-confirmation.mjs';
import {rulesPreviewMarkup} from '../rules-preview.mjs';
import {celebrationMarkup} from '../result-motion.mjs';
import {bindMiddleConfirm} from '../middle-confirm.mjs';
export const VERTICE_STORAGE_KEY='intuicao.vertice.v1';
const names=['Jogador 1','Jogador 2'],marks=['●','◆'];
const modes=['local','competitive','bot','training'],difficulties=['beginner','intermediate','strong'];
const coord=cell=>`L${Math.floor(cell/3)+1}C${cell%3+1}`;
const defaultConfig=()=>({mode:'local',difficulty:'intermediate',mascots:[...DEFAULT_MASCOTS]});
const validConfig=c=>c&&modes.includes(c.mode)&&difficulties.includes(c.difficulty)&&normalizeMascots(c.mascots)!==null;
function pointMarkup(control){return `<span class="ve-empty ve-${typeof control==='number'?'controlled ve-player-'+control:control}" aria-hidden="true">${typeof control==='number'?`<small>${marks[control]}</small>`:''}</span>`;}
const retryIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>';
function description(position,cell){const control=position.control[cell],counts=position.influence[cell];if(control==='occupied')return `Peça do ${names[position.board[cell]]}.`;if(control==='disputed')return `Disputado: ${counts[0]} apoios do Jogador 1 e ${counts[1]} do Jogador 2. Não pontua para ninguém.`;if(typeof control==='number')return `Controlado pelo ${names[control]}: ${counts[control]} apoios. Continua vazio.`;return `Neutro: ${counts[0]} apoios do Jogador 1 e ${counts[1]} do Jogador 2. Falta um segundo apoio do mesmo jogador.`;}
function mesh(position,inspection=-1){const supports=inspection>=0?position.supports[inspection].flat():[];return `<svg class="ve-mesh" viewBox="0 0 300 300" aria-hidden="true">${VERTICE_EDGES.map(([a,b])=>`<line x1="${a%3*100+50}" y1="${Math.floor(a/3)*100+50}" x2="${b%3*100+50}" y2="${Math.floor(b/3)*100+50}" class="${(a===inspection&&supports.includes(b))||(b===inspection&&supports.includes(a))?'ve-support-edge':''}"/>`).join('')}</svg>`;}
export function initVertice(){
 const host=document.getElementById('vertice'),$=id=>host.querySelector('#'+id),restart=createRestartConfirmation('restart-vertice'),search=createVerticeSearch();
 let state=null,config=defaultConfig(),screen='selection',active=false,rulesOpen=true,selected=-1,destination=-1,inspection=-1,focusCell=0,message='',hint='',hintTier=0,thinking=false,animation=null,timer=null,effectTimer=null,revision=0,matchId='',invalidSave=false,storageWarning=false,middle=null,tutorialStep=0,restoringFocus=false;
 try{const raw=JSON.parse(localStorage.getItem(VERTICE_STORAGE_KEY)||'null');if(raw){const loaded=raw.version===1&&validConfig(raw.config)?restoreVertice(raw.state):null;if(loaded&&typeof raw.matchId==='string'&&raw.matchId){state=loaded;config={...structuredClone(raw.config),mascots:normalizeMascots(raw.config.mascots)};matchId=raw.matchId;screen=raw.lastView?.screen==='play'?'play':'selection';}else invalidSave=true;}}catch{invalidSave=true;}
 const piece=(player,ghost=false)=>`<span class="ve-piece ve-player-${player}${ghost?' ve-ghost':''}" aria-hidden="true">${mascotIcon(config.mascots[player])}<small class="ve-piece-mark">${marks[player]}</small></span>`;
 const botTurn=()=>config.mode==='bot'&&state?.player===1&&!state.over;
 function persist(){if(!state||invalidSave)return;try{localStorage.setItem(VERTICE_STORAGE_KEY,JSON.stringify({version:1,config,state:JSON.parse(serializeVertice(state)),matchId,lastView:{active,screen}}));storageWarning=false;}catch{storageWarning=true;}if($('ve-save-warning'))$('ve-save-warning').hidden=!storageWarning;}
 function cancelWork(){revision++;search.cancel();thinking=false;clearTimeout(timer);clearTimeout(effectTimer);timer=null;effectTimer=null;animation=null;middle?.cancel();$('ve-board-wrap')?.classList.remove('result-success','result-failure');$('ve-board-wrap')?.querySelector('.victory-celebration')?.remove();}
 function clearSelection(){selected=-1;destination=-1;inspection=-1;hint='';hintTier=0;}
 function newId(){return `vertice-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
 function renderSelection(){middle?.destroy();middle=null;host.innerHTML=`<div class="level-screen ve-selection"><h2 id="ve-selection-title" tabindex="-1">VÉRTICE ·</h2><p>Controle simultaneamente os três pontos vazios do tabuleiro.</p>${rulesPreviewMarkup('vertice')}<div class="ve-identities">${names.map((name,p)=>`<div class="ve-player-card ve-player-${p}"><div class="ve-identity-heading"><span id="ve-mascot-preview-${p}">${piece(p)}</span><strong>${name} · ${p===0?'azul ●':'lilás ◆'}</strong></div><label>Personagem<select id="ve-mascot-${p}" aria-label="Personagem do ${name}">${mascotOptions(config.mascots[p])}</select></label></div>`).join('')}</div><details class="rules-more"><summary>Quatro demonstrações rápidas</summary><div id="ve-example"></div></details><div class="collection-toolbar ve-setup-controls"><label>Modo <select id="ve-mode"><option value="local" ${config.mode==='local'?'selected':''}>Dois jogadores locais</option><option value="competitive" ${config.mode==='competitive'?'selected':''}>Duelo local competitivo</option><option value="bot" ${config.mode==='bot'?'selected':''}>Contra o bot</option><option value="training" ${config.mode==='training'?'selected':''}>Treino com análise</option></select></label><label id="ve-difficulty-label" ${config.mode==='bot'?'':'hidden'}>Bot <select id="ve-difficulty"><option value="beginner" ${config.difficulty==='beginner'?'selected':''}>Explorador</option><option value="intermediate" ${config.difficulty==='intermediate'?'selected':''}>Intermediário</option><option value="strong" ${config.difficulty==='strong'?'selected':''}>Avançado · busca limitada</option></select></label><button id="ve-start" class="primary">Iniciar partida</button></div><p class="collection-small">Começa o Jogador 1. Contra o bot, você controla o time azul. Os personagens são apenas visuais; os dois jogadores podem escolher o mesmo animal. Os apoios podem ficar em linha reta ou formar uma curva.</p>${invalidSave?'<p role="status">O registro de VÉRTICE é inválido ou incompatível. Ele foi preservado; iniciar uma nova partida o substituirá. Outros jogos não foram alterados.</p>':''}</div>`;
 names.forEach((_,p)=>{$('ve-mascot-'+p).onchange=e=>{const next=[...config.mascots];next[p]=e.target.value;const validated=normalizeMascots(next);if(!validated)return;config={...config,mascots:validated};$('ve-mascot-preview-'+p).innerHTML=piece(p);renderTutorial();};});
 $('ve-mode').onchange=e=>{config={...config,mode:e.target.value};$('ve-difficulty-label').hidden=config.mode!=='bot';};$('ve-difficulty').onchange=e=>{config={...config,difficulty:e.target.value};};$('ve-start').onclick=()=>{cancelWork();state=createVertice();matchId=newId();invalidSave=false;enterPlay();};renderTutorial();}
 function enterPlay(){cancelWork();restart.dismiss();active=true;host.hidden=false;screen='play';rulesOpen=true;clearSelection();focusCell=state.board.findIndex(v=>v===state.player);if(focusCell<0)focusCell=0;message='';renderPlay();persist();$('ve-title')?.focus({preventScroll:true});scheduleBot();}
 function rulesMarkup(){return `<aside id="ve-rules-sidebar" class="rules-sidebar" ${rulesOpen?'':'hidden'} aria-label="Regras e como jogar"><h3>O controle pertence ao ponto vazio</h3><div class="rules-body"><p>Mova uma peça sua para um ponto vizinho vazio. Um ponto vazio é seu quando toca pelo menos duas peças suas e não recebe dois apoios do adversário. Controle os três pontos vazios ao mesmo tempo para vencer.</p><p><strong>Os apoios podem ficar em linha reta ou formar uma curva.</strong> Uma peça acima e outra à esquerda também apoiam o mesmo ponto. Ambas precisam ser vizinhas imediatas.</p><p>O centro fica disputado quando recebe dois apoios de cada jogador e não pontua para ninguém. Um ponto ocupado nunca pontua. Cada vazio vale no máximo um ponto; o controle é recalculado para os dois lados a cada movimento.</p><p>Pode entrar em qualquer ponto vizinho vazio, mesmo controlado ou disputado. Não há captura, salto, diagonal ou bloqueio permanente. Uma jogada pode dar a vitória ao adversário ao liberar o terceiro ponto dele.</p><details class="rules-more"><summary>Quatro demonstrações rápidas</summary><div id="ve-example"></div></details><details class="rules-more"><summary>Empates e duração</summary><p>A vitória tem prioridade. Sem vitória, há empate se o próximo jogador não puder mover, se a mesma ocupação e jogador da vez aparecerem pela terceira vez ou após 60 jogadas confirmadas. A abertura conta como primeira ocorrência. Não há desempate por maioria de pontos.</p></details><details class="rules-more"><summary>Controles e acessibilidade</summary><p>Setas percorrem os pontos. Enter ou espaço seleciona uma peça ou destino; ative o mesmo destino novamente ou use Confirmar jogada. Escape cancela. Foque um ponto vazio para consultar seus apoios. As bordas azuis com ● e lilases com ◆ distinguem os jogadores, mesmo quando escolhem o mesmo personagem.</p><p>No amistoso, desfazer e refazer exigem acordo. Contra o bot, desfazer retorna à decisão humana. O competitivo não oferece desfazer, reinício em andamento ou recomendações estratégicas.</p></details><details class="rules-more"><summary>Entender as escolhas</summary><p>Controle não é posse permanente: mover um apoio ou ocupar um vazio muda o placar. O bot considera os dois jogadores, mobilidade, repetição e limite de ações; a busca é limitada, não uma prova de vitória.</p></details></div></aside>`;}
 function renderPlay(){middle?.destroy();middle=null;host.innerHTML=`<div class="collection-lab ve-lab"><button id="ve-new" class="quiet" ${config.mode==='competitive'&&!state.over?'disabled':''}>← Nova partida</button><div class="lab-heading"><div><h2 id="ve-title" tabindex="-1">VÉRTICE ·</h2><p class="ve-objective">Controle os três pontos vazios.</p></div></div><div class="collection-workspace ve-workspace"><div class="collection-surface experiment ve-surface"><div class="stage-tools">${config.mode!=='competitive'?'<button id="ve-undo" aria-label="Desfazer" title="Desfazer">↶</button><button id="ve-redo" aria-label="Refazer" title="Refazer">↷</button><button id="ve-reset" class="action-reset">↺ Reiniciar</button>':'<span class="collection-small">Duelo competitivo</span>'}<details id="ve-rules-panel" class="rules-card" ${rulesOpen?'open':''}><summary id="ve-rules" aria-controls="ve-rules-sidebar" aria-expanded="${rulesOpen}"><span>Regras e como jogar</span><span class="rules-show">Mostrar</span><span class="rules-hide">Ocultar</span></summary></details></div><div id="ve-teams" class="ve-scores"></div><p id="ve-move-count" class="ve-move-count"></p><p id="ve-turn" class="ve-turn" aria-live="polite" aria-atomic="true"></p><div id="ve-board-wrap" class="collection-board-wrap experiment ve-board-wrap"><div id="ve-board" class="collection-board ve-board" role="group" aria-label="Malha de VÉRTICE: nove pontos, doze segmentos fixos"></div></div><div class="board-check-controls ve-check"><button id="ve-confirm" class="primary confirm">Confirmar jogada</button><button id="ve-cancel" class="quiet">Cancelar prévia</button></div><p id="ve-status" class="ve-status" role="status" aria-live="polite" aria-atomic="true"></p>${config.mode==='training'?'<div class="ve-help"><button id="ve-hint" class="action-hint">✦ Explicar posição</button><p id="ve-hint-text" class="hint" role="status"></p></div>':''}<div id="ve-result"></div><p id="ve-save-warning" role="status" ${storageWarning?'':'hidden'}>Não foi possível salvar neste navegador. A partida pode continuar nesta página.</p></div>${rulesMarkup()}</div></div>`;
 $('ve-new').onclick=newPreparation;if($('ve-undo'))$('ve-undo').onclick=()=>travel(false);if($('ve-redo'))$('ve-redo').onclick=()=>travel(true);if($('ve-reset'))$('ve-reset').onclick=requestReset;
 $('ve-rules-panel').ontoggle=()=>{rulesOpen=$('ve-rules-panel').open;$('ve-rules-sidebar').hidden=!rulesOpen;$('ve-rules').setAttribute('aria-expanded',String(rulesOpen));};$('ve-confirm').onclick=confirm;$('ve-cancel').onclick=cancelPreview;if($('ve-hint'))$('ve-hint').onclick=requestHint;
 $('ve-board').onclick=e=>{const b=e.target.closest('[data-ve-cell]');if(b)choose(+b.dataset.veCell);};$('ve-board').addEventListener('focusin',e=>{const b=e.target.closest('[data-ve-cell]');if(!restoringFocus&&b&&destination<0&&!animation&&!thinking&&!restart.isOpen&&state.board[+b.dataset.veCell]===null&&inspection!==+b.dataset.veCell)inspect(+b.dataset.veCell);});$('ve-board').onkeydown=e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;const b=e.target.closest('[data-ve-cell]');if(!b)return;if(e.repeat&&['Enter',' '].includes(e.key)){e.preventDefault();return;}const delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-3,ArrowDown:3}[e.key];if(delta!==undefined){e.preventDefault();const cell=+b.dataset.veCell,row=Math.floor(cell/3),col=cell%3;focusCell=(e.key==='ArrowLeft'&&col===0)||(e.key==='ArrowRight'&&col===2)||(e.key==='ArrowUp'&&row===0)||(e.key==='ArrowDown'&&row===2)?cell:cell+delta;restoreFocus(true);if(destination<0&&!animation&&!thinking&&!restart.isOpen&&state.board[focusCell]===null)inspect(focusCell);}};
 middle=bindMiddleConfirm($('ve-board'),{enabled:()=>active&&!animation&&!thinking&&destination>=0&&!state.over,onConfirm:confirm});renderBoard();renderMeta();renderTutorial();}
 function restoreFocus(focus=false){host.querySelectorAll('[data-ve-cell]').forEach(b=>b.tabIndex=+b.dataset.veCell===focusCell?0:-1);if(focus){restoringFocus=true;try{host.querySelector(`[data-ve-cell="${focusCell}"]`)?.focus({preventScroll:true});}finally{restoringFocus=false;}}}
 function renderBoard(){const board=$('ve-board');if(!board)return;const hadFocus=board.contains(document.activeElement),legal=legalVerticeMoves(state),targets=legal.filter(m=>m.from===selected).map(m=>m.to),preview=destination>=0?previewVerticeMove(state,{from:selected,to:destination}):null,visible=preview?.state||state;
 const supports=inspection>=0?visible.supports[inspection].flat():[],winPoints=state.over&&state.winner!=='draw'?state.control.flatMap((v,i)=>v===state.winner?[i]:[]):[];
 board.setAttribute('aria-busy',String(!!animation||thinking));board.innerHTML=mesh(visible,inspection)+visible.board.map((owner,cell)=>{const originReleased=preview&&cell===selected,ghost=preview&&cell===destination;return `<button type="button" data-ve-cell="${cell}" tabindex="${focusCell===cell?0:-1}" class="ve-point${selected===cell?' ve-selected':''}${targets.includes(cell)?' ve-legal':''}${originReleased?' ve-released':''}${supports.includes(cell)?' ve-support':''}${winPoints.includes(cell)?' ve-winning':''}${animation?.events.moved.to===cell?' ve-arriving':''}" style="left:${(cell%3*100+50)/3}%;top:${(Math.floor(cell/3)*100+50)/3}%" aria-label="${coord(cell)}. ${description(visible,cell)}${owner===0||owner===1?' Personagem: '+mascotName(config.mascots[owner])+'.':''}${originReleased?' Prévia: origem liberada.':''}${ghost?' Prévia: destino ocupado.':''}">${owner===0||owner===1?piece(owner,ghost):pointMarkup(visible.control[cell])}</button>`;}).join('');if(hadFocus)restoreFocus(true);}
 function renderMeta({celebrate=false}={}){if(!$('ve-teams'))return;$('ve-teams').innerHTML=names.map((name,p)=>`<section class="ve-player-card ve-player-${p}${state.player===p&&!state.over?' ve-current':''}"><div>${piece(p)}<strong>${name}</strong></div><span>Pontos controlados: <b>${state.scores[p]}/3</b></span></section>`).join('');$('ve-move-count').textContent=`Jogada ${state.turn} de 60`;
 const reasons={blocked:'Empate por bloqueio: o próximo jogador não tem movimento.',repetition:'Empate por repetição: a mesma posição e jogador da vez apareceram três vezes.',limit:'Empate: foram realizadas 60 jogadas sem vitória.'};
 $('ve-turn').textContent=state.over?(state.winner==='draw'?'A partida terminou empatada.':`${names[state.winner]} venceu!`):thinking&&botTurn()?'Jogador 2 está pensando…':`Vez do ${names[state.player]}`;$('ve-status').textContent=message||(state.over?(state.winner==='draw'?reasons[state.reason]:`${names[state.winner]} controla os três pontos vazios.`):'Selecione uma peça sua e depois um ponto vizinho vazio.');$('ve-confirm').hidden=state.over;$('ve-confirm').disabled=destination<0||thinking||!!animation||botTurn()||restart.isOpen;$('ve-cancel').hidden=(selected<0&&inspection<0)||!!animation||thinking||state.over;
 const hasHumanPast=state.history.some((_,i)=>(state.starter+i)%2===0);if($('ve-undo'))$('ve-undo').disabled=!state.history.length||(config.mode==='bot'&&!hasHumanPast);if($('ve-redo'))$('ve-redo').disabled=!state.future.length;if($('ve-hint')){$('ve-hint').disabled=state.over||!!animation||thinking;$('ve-hint-text').textContent=hint;}if($('ve-new'))$('ve-new').disabled=config.mode==='competitive'&&!state.over;
 const result=$('ve-result');result.innerHTML='';if(!state.over||animation)return;const draw=state.winner==='draw',lost=config.mode==='bot'&&state.winner===1,reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 result.innerHTML=`<div class="result-badge ve-result-badge${draw||lost?' ve-result-neutral':''}"><div>${draw?'':piece(state.winner)}<strong>${draw?'Um encontro empatado.':`${names[state.winner]} venceu!`}</strong><span>${draw?reasons[state.reason]:`Os três pontos vazios estão sob controle exclusivo do ${names[state.winner]}.${lost?' Experimente outra sequência.':''}`}</span></div></div><div class="result-retry-actions"><button id="ve-retry" type="button" class="result-retry" aria-label="Reiniciar esta partida imediatamente" title="Reiniciar esta partida imediatamente">${retryIcon}</button></div><div class="level-actions"><button id="ve-rematch" class="primary">Revanche · inverter início</button><button id="ve-new-result">Nova partida</button></div>`;$('ve-retry').onclick=resetNow;$('ve-rematch').onclick=()=>{cancelWork();state=rematchVertice(state);matchId=newId();enterPlay();};$('ve-new-result').onclick=newPreparation;
 if(celebrate&&!draw&&!reduced){const surface=$('ve-board-wrap');surface.querySelector('.victory-celebration')?.remove();if(!lost)surface.insertAdjacentHTML('beforeend',celebrationMarkup());surface.classList.add(lost?'result-failure':'result-success');effectTimer=setTimeout(()=>{surface.classList.remove('result-failure','result-success');surface.querySelector('.victory-celebration')?.remove();},1100);}}
 // A inspeção por foco não substitui os botões: preserva o alvo entre pointerdown e click.
 function inspect(cell){inspection=cell;focusCell=cell;message=`${coord(cell)}. ${description(state,cell)}`;const board=$('ve-board'),supports=state.supports[cell].flat();board.querySelectorAll('[data-ve-cell]').forEach(b=>b.classList.toggle('ve-support',supports.includes(+b.dataset.veCell)));board.querySelector('.ve-mesh').outerHTML=mesh(state,cell);restoreFocus();renderMeta();}
 function choose(cell){if(thinking&&config.mode==='training'){revision++;search.cancel();thinking=false;}if(animation||thinking||restart.isOpen)return;focusCell=cell;
 if(state.board[cell]===null&&(state.over||botTurn())){inspect(cell);restoreFocus(true);return;}if(state.over||botTurn())return;
 if(state.board[cell]===state.player){search.cancel();hint='';hintTier=0;selected=cell;destination=-1;inspection=-1;message=legalVerticeMoves(state).some(m=>m.from===cell)?'Escolha um ponto vizinho vazio. A prévia recalcula os controles dos dois lados.':'Esta peça não tem destino vazio. Escolha outra peça sua.';renderBoard();renderMeta();restoreFocus(true);return;}
 const move={from:selected,to:cell};if(selected>=0&&legalVerticeMoves(state).some(m=>m.from===move.from&&m.to===move.to)){if(destination===cell){confirm();return;}destination=cell;inspection=-1;const simulation=previewVerticeMove(state,move);message=`Prévia: ${coord(selected)} → ${coord(cell)}. Controle previsto: Jogador 1 ${simulation.state.scores[0]}/3; Jogador 2 ${simulation.state.scores[1]}/3. O placar definitivo ainda não mudou.`;renderBoard();renderMeta();restoreFocus(true);return;}
 if(state.board[cell]===null){inspection=cell;message=`${description(state,cell)} ${selected<0?'Selecione uma peça sua para mover.':'Esse ponto não é vizinho da peça selecionada.'}`;renderBoard();renderMeta();restoreFocus(true);return;}message='Essa peça pertence ao outro jogador. A seleção atual foi mantida.';renderMeta();restoreFocus(true);}
 function cancelPreview(){if(animation||thinking)return;clearSelection();message='Prévia cancelada. O tabuleiro não mudou.';renderBoard();renderMeta();restoreFocus(true);}
 function commit(move,{computer=false}={}){if(state.over||animation||restart.isOpen||!active||host.hidden||(!computer&&botTurn()))return;const before=state;let resolved;try{resolved=applyVerticeMove(state,move,{expectedPlayer:state.player,expectedTurn:state.turn});}catch(error){message=error.message;renderMeta();return;}cancelWork();state=resolved.state;clearSelection();message=`${names[before.player]}: ${coord(move.from)} → ${coord(move.to)}. Pontos controlados: ${state.scores[0]}/3 e ${state.scores[1]}/3.${state.over?(state.winner==='draw'?' A partida terminou empatada.':` ${names[state.winner]} venceu.`):''}`;persist();const token=revision,id=matchId;
 if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches){renderBoard();renderMeta();restoreFocus(!computer);scheduleBot();return;}animation={events:resolved.events};renderBoard();renderMeta();timer=setTimeout(()=>{if(token!==revision||id!==matchId||!active||host.hidden)return;animation=null;timer=null;renderBoard();renderMeta({celebrate:true});restoreFocus(!computer);scheduleBot();},300);}
 function confirm(){if(destination<0||thinking||animation)return;commit({from:selected,to:destination});}
 async function scheduleBot(){if(!active||host.hidden||screen!=='play'||!botTurn()||animation||thinking||restart.isOpen)return;thinking=true;const origin=state,token=revision,id=matchId;renderMeta();try{const result=await search.search(origin,{difficulty:config.difficulty,nodeBudget:config.difficulty==='strong'?18000:config.difficulty==='intermediate'?2500:128,seed:state.turn+state.starter*31});if(token!==revision||id!==matchId||state!==origin||!active||host.hidden||!botTurn())return;thinking=false;if(result.move)commit(result.move,{computer:true});else{message='O computador não encontrou uma jogada. Tente novamente.';renderMeta();}}catch(error){if(token!==revision||state!==origin||!active||error.name==='AbortError')return;thinking=false;message='A busca foi interrompida. Use Tentar novamente para o computador.';renderMeta();const retry=document.createElement('button');retry.textContent='Tentar novamente';retry.onclick=()=>{retry.remove();scheduleBot();};$('ve-status').append(' ',retry);}}
 function travel(redo){if(!redo&&config.mode==='bot'&&!state.history.some((_,i)=>(state.starter+i)%2===0))return;if(config.mode==='competitive'||restart.isOpen||!(redo?state.future:state.history).length)return;if(config.mode==='local'&&!globalThis.confirm?.(`Os dois jogadores concordam em ${redo?'refazer':'desfazer'} esta jogada?`))return;cancelWork();state=redo?redoVertice(state):undoVertice(state);if(config.mode==='bot'){while(state.player!==0&&!state.over&&(redo?state.future:state.history).length)state=redo?redoVertice(state):undoVertice(state);}clearSelection();message=redo?'Jogada refeita.':'Histórico restaurado.';persist();renderBoard();renderMeta();restoreFocus(true);scheduleBot();}
 function resetNow(){cancelWork();state=resetVertice(state);matchId=newId();enterPlay();}
 function requestReset(){if(config.mode==='competitive'&&!state.over)return;if(state.over){resetNow();return;}const origin=state,id=matchId;cancelWork();renderBoard();renderMeta();restart.open({match:true,isCurrent:()=>active&&!host.hidden&&state===origin&&matchId===id,onConfirm:resetNow,onCancel:()=>scheduleBot(),fallbackFocus:()=>$('ve-reset')});const dialog=document.getElementById('restart-vertice');dialog.querySelector('#restart-vertice-description').textContent='As jogadas desta partida serão descartadas. A abertura e o jogador que começou serão mantidos; as contagens de repetição e jogadas serão reiniciadas. Confirme com o acordo das duas pessoas no duelo local.';}
 function newPreparation(){if(config.mode==='competitive'&&!state.over)return;if(!state.over&&!globalThis.confirm?.('Encerrar esta partida e preparar outra? No duelo local, os dois jogadores devem concordar.'))return;cancelWork();restart.dismiss();clearSelection();screen='selection';persist();renderSelection();$('ve-selection-title').focus({preventScroll:true});}
 async function requestHint(){if(config.mode!=='training'||state.over||animation||thinking)return;hintTier++;if(hintTier===1){hint=`Observação: os controles atuais são ${state.scores[0]}/3 e ${state.scores[1]}/3. Foque cada vazio para ver os apoios diretos que explicam seu estado.`;renderMeta();return;}if(hintTier===2){hint='Explicação: liberar a origem e ocupar o destino afeta os dois jogadores. Um apoio em curva vale tanto quanto um alinhado; ocupar um ponto faz com que ele deixe de pontuar.';renderMeta();return;}thinking=true;const origin=state,token=revision,id=matchId;renderMeta();try{const result=await search.search(origin,{difficulty:'strong',nodeBudget:12000,seed:state.turn});if(origin!==state||token!==revision||id!==matchId||!active||host.hidden)return;thinking=false;hint=result.move?`Recomendação de busca limitada: ${coord(result.move.from)} → ${coord(result.move.to)}. Foram examinados ${result.nodes} nós, até profundidade ${result.depth}. Não é prova de vitória.`:'Não há movimento a recomendar.';renderMeta();}catch(error){if(token!==revision||error.name==='AbortError')return;thinking=false;hint='A análise não pôde ser concluída. A partida continua disponível.';renderMeta();}}
 function renderTutorial(){const el=$('ve-example');if(!el)return;
 const boards=[[0,0,1,null,null,null,1,0,1],[1,0,1,0,null,null,1,null,0]],opening=createVertice();let position,target=4,text;
 if(tutorialStep===0){const board=boards[0];position={board,...deriveControl(board)};text='Dois apoios em linha reta, acima e abaixo, controlam o centro vazio. Um ponto controlado vale apenas uma unidade.';}
 else if(tutorialStep===1){const board=boards[1];position={board,...deriveControl(board)};text='Apoios em curva: acima e à esquerda também contam. Neste exemplo, o centro recebe dois apoios azuis e nenhum lilás: controle exclusivo do Jogador 1.';}
 else if(tutorialStep===2){position=opening;text='Na abertura real, o centro tem dois apoios de cada jogador: disputado, vale zero para os dois. Os outros vazios são neutros.';}
 else{position=applyVerticeMove(opening,VERTICE_WIN_EXAMPLE[0]).state;target=1;text='Mover L1C2 → L1C3 libera a origem e ocupa um antigo vazio. Os controles dos dois jogadores mudam para 1/3; nenhuma conquista é permanente.';}
 el.innerHTML=`<p>Demonstração separada da partida · ${tutorialStep+1} de 4.</p><div class="ve-example-mesh" role="img" aria-label="${text}">${mesh(position,target)}${position.board.map((owner,cell)=>`<span class="ve-demo-point" style="left:${(cell%3*100+50)/3}%;top:${(Math.floor(cell/3)*100+50)/3}%">${owner===null?pointMarkup(position.control[cell]):piece(owner)}</span>`).join('')}</div><p role="status">${text}</p><button id="ve-example-next">${tutorialStep===3?'Recomeçar exemplos':'Próxima demonstração →'}</button>`;$('ve-example-next').onclick=()=>{tutorialStep=(tutorialStep+1)%4;renderTutorial();$('ve-example-next').focus({preventScroll:true});};}
 
 host.addEventListener('keydown',e=>{if(host.hidden||restart.isOpen||e.target.closest('input,select,textarea,a,dialog,[contenteditable]'))return;if(e.key==='Escape'&&(selected>=0||inspection>=0)){e.preventDefault();cancelPreview();}});
 host.addEventListener('pointerdown',e=>{if((selected>=0||inspection>=0)&&!animation&&!thinking&&!e.target.closest('#ve-board,#ve-confirm,#ve-cancel')){clearSelection();message='';renderBoard();renderMeta();}});globalThis.addEventListener('pagehide',persist);
 return{activate(){active=true;host.hidden=false;screen='selection';renderSelection();$('ve-selection-title').focus({preventScroll:true});},hide(){cancelWork();restart.dismiss();middle?.destroy();middle=null;clearSelection();active=false;host.hidden=true;persist();},restoreOnLoad(){if(!state||screen!=='play')return false;enterPlay();return true;}};
}
